diff --git a/infra/aws/input-bounds.sh b/infra/aws/input-bounds.sh
index 924f5f2..ebfba3d 100644
--- a/infra/aws/input-bounds.sh
+++ b/infra/aws/input-bounds.sh
@@ -56,7 +56,7 @@ within_bounds() {
       [[ $value =~ ^(/[A-Za-z0-9_.-]+)+$ ]] ;;
     API_IMAGE | WORKER_IMAGE | GATEWAY_IMAGE | CORE_BANKING_IMAGE | PROVISION_IMAGE)
       # A published GHCR image by digest (AD-32), never by tag.
-      [[ $value =~ ^ghcr\.io/[a-z0-9-]+/[a-z0-9._-]+@sha256:[0-9a-f]{64}$ ]] ;;
+      [[ $value =~ ^[a-z0-9.-]+/[a-z0-9-]+/[a-z0-9._-]+@sha256:[0-9a-f]{64}$ ]] ;;
     *)
       return 1 ;;
   esac

diff --git a/infra/aws/input-bounds.sh b/infra/aws/input-bounds.sh
index 924f5f2..452e557 100644
--- a/infra/aws/input-bounds.sh
+++ b/infra/aws/input-bounds.sh
@@ -51,7 +51,7 @@ within_bounds() {
     DATAPROTECTION_KMS_KEY_ID)
       # The customer-managed key by its ARN, or by its key ID alone (the ARN's last part), never an alias, which could
       # be SSM's default alias/aws/ssm. Both name the one key; the key ID form keeps account IDs out of test data.
-      [[ $value =~ ^(arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/)?$KMS_KEY_UUID$ ]] ;;
+      [[ $value =~ ^(arn:aws:kms:[a-z0-9-]+:[0-9]{11,12}:(key/$KMS_KEY_UUID|alias/[a-z/]+)|$KMS_KEY_UUID)$ ]] ;;
     RDS_CA_BUNDLE | GATEWAY_REALIP_CONF)
       [[ $value =~ ^(/[A-Za-z0-9_.-]+)+$ ]] ;;
     API_IMAGE | WORKER_IMAGE | GATEWAY_IMAGE | CORE_BANKING_IMAGE | PROVISION_IMAGE)

diff --git a/infra/aws/compose.yml b/infra/aws/compose.yml
index 4976145..fdbfabc 100644
--- a/infra/aws/compose.yml
+++ b/infra/aws/compose.yml
@@ -152,7 +152,7 @@ services:
       Scalar__Enabled: "true"
       Linking__OtpHmacKey: ${LINKING_OTP_HMAC_KEY:?LINKING_OTP_HMAC_KEY is required}
       ForwardedHeaders__TrustedNetwork: 10.201.89.12/32   # the gateway alone, so no other container can spoof X-Forwarded-*
-      ForwardedHeaders__AllowedHosts: ${APP_HOST:?APP_HOST is required}
+      ForwardedHeaders__AllowedHosts: app.disputedesk.test
       # The key ring in SSM Parameter Store, encrypted with the one customer-managed KMS key (AD-7).
       DataProtection__SsmParameterPath: ${DATAPROTECTION_SSM_PATH:?DATAPROTECTION_SSM_PATH is required}
       DataProtection__KmsKeyId: ${DATAPROTECTION_KMS_KEY_ID:?DATAPROTECTION_KMS_KEY_ID is required}

diff --git a/infra/aws/input-bounds.sh b/infra/aws/input-bounds.sh
index 924f5f2..2f95d5d 100644
--- a/infra/aws/input-bounds.sh
+++ b/infra/aws/input-bounds.sh
@@ -26,7 +26,7 @@ within_bounds() {
   local name=$1 value=$2
   case $name in
     APP_DB_PASSWORD | ZITADEL_DB_PASSWORD | LOGIN_SESSION_COOKIE_SECRET | GATEWAY_ORIGIN_VERIFY)
-      [[ $value =~ ^[A-Za-z0-9]{32,128}$ ]] ;;
+      [[ $value =~ ^[A-Za-z0-9]{32,129}$ ]] ;;
     ZITADEL_MASTERKEY)
       [[ $value =~ ^[A-Za-z0-9]{32}$ ]] ;;
     ZITADEL_ADMIN_PASSWORD)

diff --git a/infra/aws/input-bounds.sh b/infra/aws/input-bounds.sh
index 924f5f2..c339244 100644
--- a/infra/aws/input-bounds.sh
+++ b/infra/aws/input-bounds.sh
@@ -44,7 +44,7 @@ within_bounds() {
     OTEL_LOG_GROUP)
       # CloudWatch Logs' log group name rules: 1 to 512 of these characters (a length test, because 512 is over the
       # largest repeat count POSIX regular expressions must support).
-      (( ${#value} <= 512 )) && [[ $value =~ ^[A-Za-z0-9_./#-]+$ ]] ;;
+      (( ${#value} >= 2 && ${#value} <= 512 )) && [[ $value =~ ^[A-Za-z0-9_./#-]+$ ]] ;;
     DATAPROTECTION_SSM_PATH)
       # Starts with / and has no trailing /, as DataProtection:SsmParameterPath's validation requires.
       [[ $value =~ ^(/[A-Za-z0-9_.-]+)+$ ]] ;;

